def _canonicalize_args(args: Any) -> Any:
    """Recursively canonicalize args: sort dict keys, convert tuples to lists, trim string whitespace."""
    if isinstance(args, dict):
        return {k: _canonicalize_args(v) for k, v in sorted(args.items())}
    if isinstance(args, (list, tuple)):
        return [_canonicalize_args(item) for item in args]
    if isinstance(args, str):
        return args.strip()
    return args


class ToolCalls(Type):
    class ToolCall(BaseModel):
        name: str
        args: dict[str, Any]
        fingerprint: str
        id: str

        def __init__(self, **data):
            super().__init__(**data)
            canonical = {"name": self.name, "args": _canonicalize_args(self.args)}
            canonical_json = json.dumps(canonical, sort_keys=True, separators=(",", ":"))
            digest = hashlib.sha256(canonical_json.encode("utf-8")).hexdigest()
            object.__setattr__(self, "fingerprint", digest)
            object.__setattr__(self, "id", digest[:8])

